use super::*;
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IllegalArgumentException","RuntimeException","StringIndexOutOfBoundsException","NumberFormatException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn cell(p:&Value)->Rc<CellReference>{Rc::new(CellReference::CellReference__sheet(p["sheet"].as_str().map(str::to_string),p["row"].as_i64().unwrap()as i32,p["col"].as_i64().unwrap()as i32,p["ra"].as_bool().unwrap(),p["ca"].as_bool().unwrap()))}
fn cellValue(c:&CellReference)->Value{json!({"row":c.getRow(),"col":c.getCol(),"sheet":c.getSheetName(),"ra":c.isRowAbsolute(),"ca":c.isColAbsolute(),"format":call(||c.formatAsString())})}
fn area(p:&Value,sv:SpreadsheetVersion)->Value{let mut a=None;let mut ends=None;let mut out=json!({"construct":call(||{a=Some(match p["mode"].as_str().unwrap(){"cells"=>{let f=cell(&p["first"]);let l=cell(&p["last"]);ends=Some((f.clone(),l.clone()));AreaReference::fromCells(f,l)},"row"=>AreaReference::getWholeRow(p["start"].as_str(),p["end"].as_str(),sv).unwrap_or_else(|e|panic!("{e}")),"col"=>AreaReference::getWholeColumn(p["start"].as_str(),p["end"].as_str(),sv).unwrap_or_else(|e|panic!("{e}")),_=>AreaReference::new(p["text"].as_str().expect("NullPointerException"),sv).unwrap_or_else(|e|panic!("{e}"))});})});let Some(x)=a else{return out;};out["first"]=cellValue(x.getFirstCell());out["last"]=cellValue(x.getLastCell());out["sameEnds"]=json!(Rc::ptr_eq(&x._firstCell,&x._lastCell));out["firstSame"]=json!(ends.as_ref().is_some_and(|(f,_)|Rc::ptr_eq(&x._firstCell,f)));out["lastSame"]=json!(ends.as_ref().is_some_and(|(_,l)|Rc::ptr_eq(&x._lastCell,l)));out["single"]=json!(x.isSingleCell());out["wholeRow"]=json!(AreaReference::isWholeRowReference(x.getFirstCell(),x.getLastCell()));out["wholeCol"]=json!(AreaReference::isWholeColumnReference(x.getFirstCell(),x.getLastCell()));out["format"]=call(||x.formatAsString());out["string"]=call(||x.toString());out["rc"]=json!((0..3).map(|n|{let f=if n==0{None}else{Some(CellRangeAddressBase::CellRangeAddressBase(if n==1{0}else{4},9,if n==1{0}else{5},12))};let o=if n==0{None}else{Some(CellRangeAddressBase::CellRangeAddressBase(if n==1{0}else{2},9,if n==1{0}else{3},12))};call(||x.formatAsRCString(f.as_ref(),o.as_ref()))}).collect::<Vec<_>>());if p["all"]==true{out["all"]=call(||x.getAllReferencedCells().iter().map(|c|json!({"value":cellValue(c),"sameFirst":Rc::ptr_eq(c,&x._firstCell),"sameLast":Rc::ptr_eq(c,&x._lastCell)})).collect::<Vec<_>>());}out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]
fn original_android_area_reference_formatting(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/area-format-r0b54");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut actual=json!({});for sv in[SpreadsheetVersion::EXCEL97,SpreadsheetVersion::EXCEL2007]{*CUR_VERSION.lock().unwrap()=sv;actual[if sv==SpreadsheetVersion::EXCEL97{"EXCEL97"}else{"EXCEL2007"}]=json!({"cases":input["cases"].as_array().unwrap().iter().map(|p|area(p,sv)).collect::<Vec<_>>(),"generate":input["generate"].as_array().unwrap().iter().map(|s|call(||AreaReference::generateContiguous(s.as_str().expect("NullPointerException"),sv).unwrap_or_else(|e|panic!("{e}")).iter().map(|a|a.formatAsString()).collect::<Vec<_>>())).collect::<Vec<_>>()});}std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
